namespace {
    namespace td = gf::toplevelDrag;

    constexpr uint32_t kGlobalVersion = 1;

    // wl_data_device.start_drag is request 0 of wl_data_device (wayland.xml); the name and the resource's class are compared too.
    constexpr int              kStartDragOpcode = 0;
    constexpr std::string_view kStartDrag       = "start_drag";
    constexpr std::string_view kDataDevice      = "wl_data_device";
    constexpr std::string_view kDropPerformed   = "dnd_drop_performed";
    constexpr std::string_view kCancelled       = "cancelled";
    // wl_data_device.set_selection is request 1: a toplevel-drag source used as a selection is invalid_source (the spec).
    constexpr int              kSetSelectionOpcode = 1;
    constexpr std::string_view kSetSelection       = "set_selection";

    struct SObject;

    // libwayland destroy listener on the object's wl_data_source: the source's address is compared in the protocol logger, so a
    // destroyed source is forgotten before its memory can be reused. `listener` first: the notify finds its wrapper from it.
    struct SSourceListener {
        wl_listener listener{};
        SObject*    owner = nullptr;
    };

    // One xdg_toplevel_drag_v1 object.
    struct SObject {
        UP<CXdgToplevelDragV1>   resource;
        td::CDrag                drag;
        wl_resource*             source = nullptr; // its wl_data_source (compared; valid while `listening`)
        SSourceListener          sourceGone;
        bool                     listening = false;
        WP<CXDGToplevelResource> toplevel; // the toplevel attached now
        CHyprSignalListener      toplevelGone;
        CBox                     pressBox;         // the window's box at its first step (fitAfterDrop at a drop on another output)
        wl_resource*             manager   = nullptr; // the manager resource that made it (compared with the live managers)
        bool                     fed       = false; // this drag fed the tiler's preview (dragDone at its end)
        bool                     moved     = false; // this drag moved the window (followOutput, fitAfterDrop at its end)
        bool                     live      = true;  // false: inert (runtime unload), requests ignored
        bool                     refused   = false; // one log line for a window the drag cannot move
        bool                     logged    = false; // one log line when its drag begins

        SObject()                          = default;
        SObject(const SObject&)            = delete; // the source's listener points at this object
        SObject& operator=(const SObject&) = delete;
        SObject(SObject&&)                 = delete;
        SObject& operator=(SObject&&)      = delete;
        ~SObject() {
            if (listening)
                wl_list_remove(&sourceGone.listener.link); // never left in the source's list (its notify is code of this library)
        }

        uint64_t id() const {
            return reinterpret_cast<uintptr_t>(this);
        }
    };

    // One binding of the xdg_toplevel_drag_manager_v1 global.
    struct SManager {
        UP<CXdgToplevelDragManagerV1> resource;
        wl_resource*                  raw  = nullptr; // its wl_resource, kept for the objects' back reference (cleared with it)
        bool                          live = true;
    };

    struct SObjects {
        std::vector<UP<SManager>> managers;
        std::vector<UP<SObject>>  objects;
    };

    // A drag that ended, finished from the event loop (the protocol logger's callback only records).
    struct SEnd {
        PHLWINDOWREF window; // the window that followed the pointer (expired: none, or gone since)
        td::Outcome  outcome = td::Outcome::Cancel;
        bool         fed     = false;
        bool         moved   = false; // the drag moved the window: only then it takes the Desktop under it and fits there
        CBox         pressBox;
    };

    struct SState {
        wl_global*                       global = nullptr;
        bool                             ready  = false;
        SObjects                         live;
        td::CSources                     sources;
        wl_protocol_logger*              logger = nullptr;
        std::vector<CHyprSignalListener> listeners;
        std::vector<SEnd>                ends;
        std::vector<uint64_t>            misused;                // objects whose source went to set_selection (invalid_source)
        gf::deferredFocus::CLater        endLater;               // finishes `ends` (its callback is code of this library)
        gf::deferredFocus::CLater        misuseLater;            // raises invalid_source for `misused` after the request
        gf::deferredFocus::CLater        loggerLater;            // removes the protocol logger once nothing waits for a drag
    };

    // Constructed on first use inside a guarded call (R13). Emptied by stop() before dlclose.
    SState& st() {
        static SState s;
        return s;
    }

    // Inert objects of clients still connected after a runtime unload (the library is pinned then). Never destroyed, as the
    // appmenu server's (AppmenuServer.cpp): entries leave when libwayland destroys their resource.
    SObjects& retired() {
        static auto* r = new SObjects;
        return *r;
    }

    uint64_t idOf(const void* p) {
        return reinterpret_cast<uintptr_t>(p);
    }

    template <typename T>
    void eraseFrom(std::vector<UP<T>>& v, const T* p) {
        std::erase_if(v, [p](const UP<T>& e) { return e.get() == p; });
    }

    pid_t clientPid(wl_client* client) {
        pid_t pid = 0;
        if (client)
            wl_client_get_credentials(client, &pid, nullptr, nullptr);
        return pid;
    }

    PHLWINDOW windowOf(const SObject& o) {
        const auto top = o.toplevel.lock();
        return top ? top->m_window.lock() : nullptr;
    }

    // The pointer as the motion event gives it (CInputManager::mouseMoveUnified emits the floored position): one coordinate
    // source for every step, so a window placed at its map or attach does not move by a fraction of a pixel at the next motion.
    Vector2D pointerNow() {
        return g_pInputManager ? g_pInputManager->getMouseCoordsInternal().floor() : Vector2D{};
    }

    // Hyprland runs a drag and drop now (CWLDataDeviceProtocol's current source is alive).
    bool hyprlandDragRunning() {
        return PROTO::data && PROTO::data->dndActive();
    }

    // The object whose attached window is out of the drag target's selection now (core excludes(): its drag runs, the window
    // attached and mapped; it also follows the pointer until the release). One seat: at most one drag runs. A window Hyprland
    // mapped already but whose window.open has not come yet (CWindow::onMap sets m_isMapped first, and a pointer motion
    // Hyprland simulates on the way can come before the event) counts as mapped: it is never the drag's target either.
    SObject* excluding() {
        for (const auto& o : st().live.objects) {
            if (!o->live || o->drag.phase() != td::Phase::Dragging || !o->drag.attached())
                continue;
            if (!o->drag.excludes()) {
                const auto top = o->toplevel.lock();
                const auto w   = top ? top->m_window.lock() : nullptr;
                if (w && w->m_isMapped)
                    o->drag.mapped(idOf(top.get()));
            }
            if (o->drag.excludes())
                return o.get();
        }
        return nullptr;
    }

    bool anyDragging() {
        return std::ranges::any_of(st().live.objects, [](const UP<SObject>& o) { return o->live && o->drag.phase() == td::Phase::Dragging; });
    }

    // The protocol logger is needed while an object with its source waits for its drag or runs it.
    bool loggerNeeded() {
        return std::ranges::any_of(st().live.objects,
                                   [](const UP<SObject>& o) { return o->live && o->source && o->drag.phase() != td::Phase::Ended; });
    }

    void onProtocolMessage(void* data, wl_protocol_logger_type direction, const wl_protocol_logger_message* message);

    void dropLoggerIfIdle() {
        auto& s = st();
        if (!s.logger || (s.ready && loggerNeeded()))
            return;
        wl_protocol_logger_destroy(s.logger);
        s.logger = nullptr;
    }

    // Never from inside the logger's own callback: libwayland walks its list of loggers then.
    void scheduleLoggerCheck() {
        st().loggerLater.schedule([] { gf::guarded("toplevel drag logger check", [] { dropLoggerIfIdle(); }); });
    }

    bool ensureLogger() {
        auto& s = st();
        if (s.logger)
            return true;
        if (!g_pCompositor || !g_pCompositor->m_wlDisplay)
            return false;
        s.logger = wl_display_add_protocol_logger(g_pCompositor->m_wlDisplay, onProtocolMessage, nullptr);
        if (!s.logger)
            gf::log(Log::ERR, "toplevel drag: wl_display_add_protocol_logger failed: drags are not seen, windows do not follow");
        return s.logger != nullptr;
    }

    // ---- the end of a drag -------------------------------------------------------------------------------------------

    void finish(const SEnd& e) {
        const auto w    = e.window.lock();
        const auto snap = e.outcome == td::Outcome::Drop && w ? gf::tiler::previewOf(w) : std::nullopt;
        if (e.fed)
            gf::tiler::dragDone();
        if (!w)
            return;
        // "As if an xdg_toplevel.move ended" (the spec): released over the place shown, the window takes it (tiling.md TL16);
        // elsewhere it stays and takes the Desktop of the output under it, fitting its work area (as the titlebar drag).
        bool tiled = false;
        if (snap && gf::tiler::movable(w))
            tiled = gf::tiler::tile(w, snap->place, snap->monitor.lock());
        gf::tiler::endMove(w); // no-op unless the window is still Moving
        if (e.outcome == td::Outcome::Drop && !tiled && e.moved && gf::tiler::movable(w)) {
            gf::tiler::followOutput(w);
            gf::tiler::fitAfterDrop(w, e.pressBox);
        }
        gf::logRequest(Log::INFO, "toplevel drag: window {:x} {}", idOf(w.get()),
                       e.outcome == td::Outcome::Cancel ? "cancelled: not moved further, no tile" :
                           tiled                        ? std::string_view{"dropped: tiled into the place shown"} :
                                                          std::string_view{"dropped: stays where it is"});
    }

    void finishEnds() {
        const auto ends = std::exchange(st().ends, {});
        for (const auto& e : ends)
            finish(e);
    }

    // Queues the window's end (the release's or the drag's) for the event loop.
    void queueEnd(SObject& o, const PHLWINDOW& w, const td::End& end) {
        auto& s = st();
        if (!end.toplevel && !o.fed)
            return;
        s.ends.push_back(SEnd{.window   = end.toplevel ? PHLWINDOWREF{w} : PHLWINDOWREF{},
                              .outcome  = end.outcome,
                              .fed      = std::exchange(o.fed, false),
                              .moved    = std::exchange(o.moved, false),
                              .pressBox = o.pressBox});
        s.endLater.schedule([] { gf::guarded("toplevel drag end", [] { finishEnds(); }); });
    }

    // Records the end and schedules the rest on the event loop: this may run inside the protocol logger's callback (Hyprland is
    // sending the event) or a destroy listener, so nothing here moves a window or sends anything.
    void ended(SObject& o, td::EndKind kind) {
        const auto w   = windowOf(o);
        const auto end = o.drag.end(kind);
        o.toplevelGone.reset();
        o.toplevel.reset();
        if (end)
            queueEnd(o, w, *end);
        scheduleLoggerCheck();
    }

    // ---- the protocol logger (libwayland, public API) -----------------------------------------------------------------

    // Only for the few messages whose name matched: the source map first, then the object it names.
    SObject* objectOfSource(const wl_resource* source) {
        auto& s = st();
        if (!source || s.sources.empty())
            return nullptr;
        const auto object = s.sources.objectOf(idOf(source));
        if (!object)
            return nullptr;
        for (const auto& o : s.live.objects) {
            if (o->live && o->id() == *object && o->source == source)
                return o.get();
        }
        return nullptr;
    }

    // The client of the object's manager while that manager lives (its back reference is cleared when it goes, managerGone).
    std::optional<uint64_t> managerClient(wl_resource* manager) {
        if (!manager || !std::ranges::any_of(st().live.managers, [manager](const UP<SManager>& m) { return m->live && m->raw == manager; }))
            return std::nullopt;
        return idOf(wl_resource_get_client(manager));
    }

    // The source of a toplevel drag went to wl_data_device.set_selection: invalid_source on the manager that made the object,
    // raised from the event loop (never inside libwayland's logger walk). A manager destroyed since cannot carry it: logged.
    void raiseMisuse() {
        auto&      s       = st();
        const auto misused = std::exchange(s.misused, {});
        for (const auto id : misused) {
            const auto it = std::ranges::find_if(s.live.objects, [id](const UP<SObject>& o) { return o->live && o->id() == id; });
            if (it == s.live.objects.end())
                continue;
            const auto& o      = **it;
            const auto  object = o.resource->resource();
            if (!object)
                continue;
            const auto source = o.source ? std::optional<uint64_t>{idOf(wl_resource_get_client(o.source))} : std::nullopt;
            if (!td::misuseRaisable(managerClient(o.manager), idOf(wl_resource_get_client(object)), source)) {
                gf::logRequest(Log::WARN, "toplevel drag: a source with a toplevel drag used as a selection; its manager is gone or another client's: not raised");
                continue;
            }
            gf::logRequest(Log::WARN, "toplevel drag: a source with a toplevel drag used as a selection: protocol error invalid_source");
            wl_resource_post_error((*it)->manager, XDG_TOPLEVEL_DRAG_MANAGER_V1_ERROR_INVALID_SOURCE, "data_source used for a selection");
        }
    }

    // Called by libwayland for every request (before its dispatch) and every event while the logger is installed. The message's
    // opcode and name are compared first (a few bytes), so a message other than the four a toplevel drag needs costs the same
    // however many objects clients hold; only then the source map is read. Records only.
    void onProtocolMessage(void* /*data*/, wl_protocol_logger_type direction, const wl_protocol_logger_message* message) {
        try {
            auto& s = st();
            if (!s.ready || s.sources.empty() || !message || !message->resource || !message->message || !message->message->name)
                return;
            const std::string_view name = message->message->name;
            if (direction == WL_PROTOCOL_LOGGER_REQUEST) {
                const bool start     = message->message_opcode == kStartDragOpcode && name == kStartDrag;
                const bool selection = message->message_opcode == kSetSelectionOpcode && name == kSetSelection;
                if (!start && !selection)
                    return;
                const char* cls = wl_resource_get_class(message->resource);
                if (!cls || std::string_view{cls} != kDataDevice || message->arguments_count < 1 || !message->arguments)
                    return;
                // libwayland's server closures hold object arguments as their wl_resource (its first member is the wl_object).
                auto* o = objectOfSource(reinterpret_cast<const wl_resource*>(message->arguments[0].o));
                if (!o)
                    return;
                if (selection) {
                    s.misused.push_back(o->id());
                    s.misuseLater.schedule([] { gf::guarded("toplevel drag invalid_source", [] { raiseMisuse(); }); });
                    return;
                }
                if (o->drag.start() && !std::exchange(o->logged, true))
                    gf::logRequest(Log::INFO, "toplevel drag: drag began (source {:x}, pid {})", idOf(o->source), clientPid(wl_resource_get_client(o->source)));
                return;
            }
            const bool dropped = name == kDropPerformed;
            if (!dropped && name != kCancelled)
                return;
            if (auto* o = objectOfSource(message->resource))
                ended(*o, dropped ? td::EndKind::DropPerformed : td::EndKind::Cancelled);
        } catch (...) { // NOLINT(bugprone-empty-catch): called from libwayland; nothing may escape, nothing to report to here
        }
    }

    // ---- the source's destroy listener ---------------------------------------------------------------------------------

    void stopListening(SObject& o) {
        if (!o.listening)
            return;
        wl_list_remove(&o.sourceGone.listener.link);
        wl_list_init(&o.sourceGone.listener.link);
        o.listening = false;
    }

    void onSourceDestroyed(wl_listener* listener, void* /*data*/) {
        gf::guarded("toplevel drag source destroyed", [listener] {
            auto* wrap = reinterpret_cast<SSourceListener*>(listener); // `listener` is its first member
            auto* o    = wrap->owner;
            if (!o)
                return;
            stopListening(*o);
            st().sources.removeSource(idOf(o->source));
            o->source = nullptr;
            if (o->live)
                ended(*o, td::EndKind::SourceGone);
        });
    }

    // ---- following the pointer -----------------------------------------------------------------------------------------

    bool fullscreenNow(const PHLWINDOW& w) {
        const auto& fs = Fullscreen::controller();
        return fs && fs->getFullscreenModes(w).internal != Fullscreen::FSMODE_NONE;
    }

    // Hyprland's general:snap:enabled and misc:animate_mouse_windowdragging, bound once as the titlebar drag does (Titlebar.cpp).
    bool snapEnabled() {
        static const CConfigValue<Config::INTEGER> enabled("general:snap:enabled");
        return enabled.good() && *enabled != 0;
    }

    bool animateWindowDragging() {
        static const CConfigValue<Config::INTEGER> animate("misc:animate_mouse_windowdragging");
        return animate.good() && *animate != 0;
    }

    // One step of the attached window under the pointer: a floating move as the plugin's titlebar drag makes (Titlebar.cpp
    // updateMove), the tiling preview fed through dragMotion. A tiled window takes back its size from before at its first step.
    void follow(SObject& o, const PHLWINDOW& w, const Vector2D& pointer) {
        if (!g_layoutManager)
            return;
        if (!gf::tiler::movable(w) || fullscreenNow(w) || gf::tiler::inSplit(w)) {
            if (!std::exchange(o.refused, true))
                gf::logRequest(Log::INFO, "toplevel drag: window {:x} not moved (full screen, Split View, or not movable)", idOf(w.get()));
            return;
        }
        const auto target = w->layoutTarget();
        if (!target)
            return;
        CBox       box  = target->position();
        const auto step = o.drag.step(td::Point{.x = pointer.x, .y = pointer.y}, td::Point{.x = box.x, .y = box.y});
        if (!step)
            return;
        if (step->first) {
            o.pressBox = box;
            gf::logRequest(Log::INFO, "toplevel drag: window {:x} follows the pointer", idOf(w.get()));
        }
        const auto before = step->first ? gf::tiler::beginMove(w) : std::nullopt;
        if (before) {
            // TL16: out of its tile at its size from before, the pointer at the same place of it.
            const auto r = gf::titlebar::unzoomedDragBox(gf::titlebar::Rect{box.x, box.y, box.w, box.h}, before->w, before->h, pointer.x, pointer.y, pointer.x, pointer.y);
            box          = CBox{r.x, r.y, r.w, r.h};
            o.drag.regrab(td::Point{.x = pointer.x, .y = pointer.y}, td::Point{.x = box.x, .y = box.y});
        } else {
            box.x = step->topLeft.x;
            box.y = step->topLeft.y;
        }
        // TL19: away from a tiling place the window snaps as in Hyprland's own move; FR56: its top stays below the menu bar.
        if (!gf::tiler::snapFor(w, pointer) && snapEnabled()) {
            Vector2D pos  = box.pos();
            Vector2D size = box.size();
            g_layoutManager->performSnap(pos, size, target, MBIND_MOVE, -1, box.size());
            box = CBox{pos.round(), size};
        }
        box = gf::topClamp::heldMove(w, box, pointer);
        g_layoutManager->setTargetGeom(box, target);
        if (!animateWindowDragging())
            target->warpPositionSize();
        gf::tiler::dragMotion(w, pointer);
        o.fed   = true;
        o.moved = true;
    }

    // The drag's target: the surface under the pointer other than the dragged window ("the attached window does not participate
    // in the selection of the drag target"), looked up in Hyprland 0.56.2's pointer-focus order (layer popups, the Overlay and Top
    // layers, windows, the Bottom and Background layers; DesktopFocus.cpp underCursor) with the window as windowAt's
    // ignoreWindow, then given to CSeatManager::setPointerFocus, which during a drag moves the drag focus there (Hyprland's data
    // device sends leave and enter). False when Hyprland keeps the focus decision (the lock, an Exclusive layer, no output).
    bool pickTarget(const PHLWINDOW& dragged, const Vector2D& pos) {
        if (!g_pSeatManager || !Desktop::viewState() || !State::monitorState())
            return false;
        if (gf::deferredFocus::sessionLocked() || gf::deferredFocus::exclusiveLayerMapped())
            return false;
        const auto mon = State::monitorState()->query().vec(pos).run();
        if (!mon)
            return false;
        const auto             tester = Desktop::viewState()->hitTest();
        Vector2D               local;
        PHLLS                  layer;
        SP<CWLSurfaceResource> surface = tester.layerPopupSurfaceAt(pos, mon, &local, &layer);
        for (const auto level : {ZWLR_LAYER_SHELL_V1_LAYER_OVERLAY, ZWLR_LAYER_SHELL_V1_LAYER_TOP}) {
            if (!surface)
                surface = tester.layerSurfaceAt(pos, &mon->m_layerSurfaceLayers[level], &local, &layer);
        }
        bool onWindow = false;
        if (!surface) {
            if (const auto under = tester.windowAt(pos, Desktop::View::FOCUS_PRIORITY, dragged)) {
                onWindow = true; // its surface, or nothing on its border (as Hyprland)
                surface  = tester.windowSurfaceAt(pos, under, local);
            }
        }
        for (const auto level : {ZWLR_LAYER_SHELL_V1_LAYER_BOTTOM, ZWLR_LAYER_SHELL_V1_LAYER_BACKGROUND}) {
            if (!surface && !onWindow)
                surface = tester.layerSurfaceAt(pos, &mon->m_layerSurfaceLayers[level], &local, &layer);
        }
        g_pSeatManager->setPointerFocus(surface, local);
        return true;
    }

    // A drag that Hyprland ended without its end seen here (no event): a cancel.
    void endUnseen(SObject& o) {
        gf::logRequest(Log::INFO, "toplevel drag: Hyprland's drag ended unseen: cancelled");
        ended(o, td::EndKind::SourceGone);
    }

    // From the plugin's input.mouse.move listener (registered at load: before the data-device listener Hyprland registers at
    // each drag start, CWLDataDeviceProtocol::initiateDrag). Cancelling the event makes CInputManager::mouseMoveUnified return
    // right after the bus (Hyprland 0.56.2, read from the binary): its own pointer-focus pass, which would pick the dragged
    // window, does not run; the data device's listener still runs and sends the motion relative to the focus set here.
    void onPointerMotion(const Vector2D& pos, Event::SCallbackInfo& info) {
        auto& s = st();
        if (!s.ready || s.live.objects.empty())
            return;
        auto* o = excluding();
        if (!o)
            return;
        if (!hyprlandDragRunning()) {
            endUnseen(*o);
            return;
        }
        const auto w = windowOf(*o);
        if (!w || !w->m_isMapped)
            return;
        if (o->drag.follows())
            follow(*o, w, pos); // after the release it stays where it was released, still out of the target's selection
        if (pickTarget(w, pos))
            info.cancelled = true;
    }

    // From the plugin's input.mouse.button listener, before the data device's: any button's release makes Hyprland 0.56.2 drop
    // (CWLDataDeviceProtocol::dropDrag), which sends drop and leave to the target and keeps the drag's source until the target
    // finishes (wl_data_offer.finish runs completeDrag, the only sender of dnd_drop_performed), which may be late or never; a
    // drop nobody accepted is cancelled at once. So the window's drag ends at the release, as a drop (core release()): it follows
    // no more, the drag's target is Hyprland's own again, and the place shown tiles once Hyprland handled the release. Kept per
    // drag until it ends (a target that cancels later does not undo the drop).
    void onPointerButton(const IPointer::SButtonEvent& e) {
        auto& s = st();
        if (!s.ready || e.state != WL_POINTER_BUTTON_STATE_RELEASED || !anyDragging())
            return;
        for (const auto& o : s.live.objects) {
            if (!o->live)
                continue;
            const auto w   = windowOf(*o);
            const auto end = o->drag.release();
            if (!end)
                continue;
            if (end->toplevel && w)
                gf::logRequest(Log::INFO, "toplevel drag: window {:x} released: its drag ends here (Hyprland waits for the target to finish)", idOf(w.get()));
            queueEnd(*o, w, *end);
        }
    }

    // ---- windows -------------------------------------------------------------------------------------------------------

    void onWindowOpen(const PHLWINDOW& w) {
        auto& s = st();
        if (!s.ready || !w || !w->m_isMapped || s.live.objects.empty())
            return;
        for (const auto& o : s.live.objects) {
            const auto top = o->toplevel.lock();
            if (!o->live || !top || top->m_window.lock() != w)
                continue;
            o->drag.mapped(idOf(top.get()));
            // Mapped while attached during its drag (a torn-off tab's new window): under the pointer at once, at the client's offset.
            if (o->drag.follows() && hyprlandDragRunning() && g_pInputManager)
                follow(*o, w, pointerNow());
        }
    }

    // The attached window unmapped (Chromium hides it when the tab joins another strip) or its role went: detached, its
    // preview gone, a tiled window that left its tile is Free.
    void detached(SObject& o, const PHLWINDOW& w) {
        o.toplevelGone.reset();
        o.toplevel.reset();
        if (std::exchange(o.fed, false))
            gf::tiler::dragDone();
        if (w)
            gf::tiler::endMove(w);
    }

    void onWindowClose(const PHLWINDOW& w) {
        auto& s = st();
        if (!s.ready || !w || s.live.objects.empty())
            return;
        for (const auto& o : s.live.objects) {
            const auto top = o->toplevel.lock();
            if (!o->live || !top || top->m_window.lock() != w)
                continue;
            if (o->drag.unmapped(idOf(top.get()))) {
                gf::logRequest(Log::INFO, "toplevel drag: window {:x} unmapped: detached", idOf(w.get()));
                detached(*o, w);
            }
        }
    }

    void onToplevelGone(SObject* o, uint64_t toplevel) {
        if (!o->live || !o->drag.gone(toplevel))
            return;
        detached(*o, nullptr);
    }

    // ---- xdg_toplevel_drag_v1 requests ----------------------------------------------------------------------------------

    void objectGone(SObject* o) {
        if (o->live) {
            auto& s = st();
            stopListening(*o);
            s.sources.removeObject(o->id());
            if (std::exchange(o->fed, false))
                gf::tiler::dragDone();
            o->toplevelGone.reset();
            eraseFrom(s.live.objects, o); // destroys o and its wl_resource (if still alive)
            scheduleLoggerCheck();
        } else
            eraseFrom(retired().objects, o);
    }

    void onAttach(SObject* o, wl_resource* toplevelResource, int32_t x, int32_t y) {
        gf::guarded("toplevel drag attach", [&] {
            if (!o->live || !o->resource->resource())
                return;
            // fromResource reads the resource's user data unchecked: null while the role is being destroyed (ClientChrome P8).
            const auto top = toplevelResource && wl_resource_get_user_data(toplevelResource) ? CXDGToplevelResource::fromResource(toplevelResource) : nullptr;
            if (!top)
                return; // its role is gone: nothing to attach (protocol-safe no-op)
            const auto w      = top->m_window.lock();
            const bool mapped = w && w->m_isMapped;
            if (o->drag.attach(idOf(top.get()), mapped, x, y) == td::Error::ToplevelAttached) {
                gf::logRequest(Log::WARN, "toplevel drag: attach while a toplevel is attached: protocol error toplevel_attached (pid {})", clientPid(o->resource->client()));
                o->resource->error(XDG_TOPLEVEL_DRAG_V1_ERROR_TOPLEVEL_ATTACHED, "valid toplevel already attached");
                return;
            }
            // A window attached while mapped keeps the point the pointer holds now (the press, for a window's only tab).
            if (mapped && g_pInputManager) {
                if (const auto target = w->layoutTarget()) {
                    const auto pointer = pointerNow();
                    const auto box     = target->position();
                    o->drag.holdAt(td::Point{.x = pointer.x, .y = pointer.y}, td::Point{.x = box.x, .y = box.y});
                }
            }
            o->toplevel     = top;
            o->refused      = false;
            const auto id   = idOf(top.get());
            o->toplevelGone = top->m_events.destroy.listen([o, id] { gf::guarded("toplevel drag toplevel destroyed", [&] { onToplevelGone(o, id); }); });
            gf::logRequest(Log::INFO, "toplevel drag: pid {} attached window {:x} ({}), offset {},{}", clientPid(o->resource->client()), w ? idOf(w.get()) : 0,
                           mapped ? "mapped" : "not mapped yet", x, y);
        });
    }

    void onDestroy(SObject* o) {
        gf::guarded("toplevel drag destroy", [&] {
            if (o->live && o->resource->resource() && o->drag.destroy() == td::Error::OngoingDrag) {
                gf::logRequest(Log::WARN, "toplevel drag: destroyed during its drag: protocol error ongoing_drag (pid {})", clientPid(o->resource->client()));
                o->resource->error(XDG_TOPLEVEL_DRAG_V1_ERROR_ONGOING_DRAG, "drag has not ended");
                return;
            }
            objectGone(o);
        });
    }

    void onObjectDestroyed(SObject* o) {
        gf::guarded("toplevel drag object destroyed", [&] { objectGone(o); });
    }

    // ---- xdg_toplevel_drag_manager_v1 requests --------------------------------------------------------------------------

    // The objects' back references to this manager are cleared first: a manager made later (by any client) may get its address.
    void managerGone(SManager* m) {
        if (m->live) {
            for (const auto& o : st().live.objects) {
                if (o->manager == m->raw)
                    o->manager = nullptr;
            }
        }
        eraseFrom(m->live ? st().live.managers : retired().managers, m);
    }

    void onGetDrag(SManager* m, uint32_t id, wl_resource* source) {
        gf::guarded("toplevel drag get_xdg_toplevel_drag", [&] {
            auto&      s      = st();
            wl_client* client = m->resource->client();
            auto       o      = makeUnique<SObject>();
            o->resource       = makeUnique<CXdgToplevelDragV1>(client, m->resource->version(), id);
            if (!o->resource->resource()) {
                m->resource->noMemory();
                return;
            }
            o->live   = m->live && s.ready;
            auto* raw = o.get();
            raw->resource->setAttach([raw](CXdgToplevelDragV1* /*r*/, wl_resource* toplevel, int32_t x, int32_t y) { onAttach(raw, toplevel, x, y); });
            raw->resource->setDestroy([raw](CXdgToplevelDragV1* /*r*/) { onDestroy(raw); });
            raw->resource->setOnDestroy([raw](CXdgToplevelDragV1* /*r*/) { onObjectDestroyed(raw); });
            if (!raw->live) {
                retired().objects.push_back(std::move(o));
                return;
            }
            s.live.objects.push_back(std::move(o));
            if (!source)
                return; // not nullable in the XML (libwayland refuses a null object there); nothing to follow
            if (s.sources.add(idOf(source), raw->id()) == td::Error::InvalidSource) {
                gf::logRequest(Log::WARN, "toplevel drag: a second object for one data source: protocol error invalid_source (pid {})", clientPid(client));
                m->resource->error(XDG_TOPLEVEL_DRAG_MANAGER_V1_ERROR_INVALID_SOURCE, "data_source already used for toplevel drag");
                return;
            }
            raw->manager                    = m->raw;
            raw->source                     = source;
            raw->sourceGone.owner           = raw;
            raw->sourceGone.listener.notify = onSourceDestroyed;
            wl_resource_add_destroy_listener(source, &raw->sourceGone.listener);
            raw->listening = true;
            ensureLogger();
            gf::logRequest(Log::DEBUG, "toplevel drag: pid {} created a toplevel drag for source {:x}", clientPid(client), idOf(source));
        });
    }

    void onManagerDestroy(SManager* m) {
        gf::guarded("toplevel drag manager destroy", [&] { managerGone(m); });
    }

    void onManagerDestroyed(SManager* m) {
        gf::guarded("toplevel drag manager destroyed", [&] { managerGone(m); });
    }

    void bindManager(wl_client* client, void* /*data*/, uint32_t version, uint32_t id) {
        gf::guarded("toplevel drag bind", [&] {
            auto m      = makeUnique<SManager>();
            m->resource = makeUnique<CXdgToplevelDragManagerV1>(client, version, id);
            if (!m->resource->resource()) {
                wl_client_post_no_memory(client);
                return;
            }
            m->raw    = m->resource->resource();
            m->live   = st().ready;
            auto* raw = m.get();
            raw->resource->setGetXdgToplevelDrag([raw](CXdgToplevelDragManagerV1* /*r*/, uint32_t newId, wl_resource* source) { onGetDrag(raw, newId, source); });
            raw->resource->setDestroy([raw](CXdgToplevelDragManagerV1* /*r*/) { onManagerDestroy(raw); });
            raw->resource->setOnDestroy([raw](CXdgToplevelDragManagerV1* /*r*/) { onManagerDestroyed(raw); });
            if (raw->live)
                gf::logRequest(Log::INFO, "toplevel drag: client pid {} bound xdg_toplevel_drag_manager_v1 version {}", clientPid(client), version);
            (raw->live ? st().live.managers : retired().managers).push_back(std::move(m));
        });
    }

    // Keeps this library mapped after Hyprland's dlclose (live client objects point into it), as the appmenu server does.
    bool pinLibrary() {
        Dl_info info{};
        if (dladdr(reinterpret_cast<const void*>(&bindManager), &info) == 0 || !info.dli_fname)
            return false;
        void* self = dlopen(info.dli_fname, RTLD_NOW | RTLD_NOLOAD | RTLD_NODELETE);
        if (!self)
            return false;
        dlclose(self); // drops this extra reference; the object stays marked NODELETE
        return true;
    }
} // namespace

namespace gf::toplevelDrag {

    bool start() {
        auto& s = st();
        if (s.ready)
            return true;
        if (!g_pCompositor || !g_pCompositor->m_wlDisplay) {
            gf::log(Log::ERR, "toplevel drag: no Wayland display");
            return false;
        }
        // A later Hyprland that serves the protocol itself would compile hyprwayland-scanner's code for it, which exports this
        // interface symbol as Hyprland exports xdg_toplevel_interface (the plugin's own copy is hidden): clients would then see
        // two globals and bind either. Hyprland's wins: no global here (Hyprland 0.56.2 exports none, nm -D).
        if (dlsym(RTLD_DEFAULT, "xdg_toplevel_drag_manager_v1_interface")) {
            gf::log(Log::WARN, "toplevel drag: Hyprland serves xdg_toplevel_drag_manager_v1 itself: the plugin's global is not created");
            return false;
        }
        auto& bus = Event::bus();
        if (!bus)
            return false;
        s.endLater.clear(); // a previous stop() cancelled them
        s.misuseLater.clear();
        s.loggerLater.clear();
        auto& ev = bus->m_events;
        auto& l  = s.listeners;
        l.push_back(ev.input.mouse.move.listen([](Vector2D pos, Event::SCallbackInfo& info) { gf::guarded("toplevel drag motion", [&] { onPointerMotion(pos, info); }); }));
        l.push_back(ev.input.mouse.button.listen([](IPointer::SButtonEvent e, Event::SCallbackInfo& /*info*/) { gf::guarded("toplevel drag button", [&] { onPointerButton(e); }); }));
        l.push_back(ev.window.open.listen([](const PHLWINDOW& w) { gf::guarded("toplevel drag window.open", [&] { onWindowOpen(w); }); }));
        l.push_back(ev.window.close.listen([](const PHLWINDOW& w) { gf::guarded("toplevel drag window.close", [&] { onWindowClose(w); }); }));

        s.global = wl_global_create(g_pCompositor->m_wlDisplay, &xdg_toplevel_drag_manager_v1_interface, kGlobalVersion, nullptr, bindManager);
        if (!s.global) {
            gf::log(Log::ERR, "toplevel drag: wl_global_create(xdg_toplevel_drag_manager_v1) failed");
            s.listeners.clear();
            return false;
        }
        s.ready = true;
        gf::log(Log::INFO, "toplevel drag: xdg_toplevel_drag_manager_v1 version {} advertised", kGlobalVersion);
        return true;
    }

    void stop() {
        auto& s = st();
        s.listeners.clear();
        s.endLater.cancel();
        s.misuseLater.cancel();
        s.loggerLater.cancel();
        s.ends.clear();
        s.misused.clear();

        const bool   shuttingDown = !g_pCompositor || g_pCompositor->m_isShuttingDown;
        const size_t clientObjs   = s.live.managers.size() + s.live.objects.size();
        const bool   fed          = std::ranges::any_of(s.live.objects, [](const UP<SObject>& o) { return o->fed; });
        s.ready                   = false;
        if (fed && !shuttingDown)
            gf::tiler::dragDone(); // the preview of a drag in progress goes; the drag goes on as Hyprland's plain drag and drop

        // Nothing of this library may stay reachable from libwayland but the pinned objects below.
        if (s.logger) {
            wl_protocol_logger_destroy(s.logger);
            s.logger = nullptr;
        }
        for (auto& o : s.live.objects) {
            stopListening(*o);
            o->source = nullptr;
            o->toplevelGone.reset();
            o->toplevel.reset();
            o->fed = false;
        }
        s.sources = td::CSources{};

        if (!shuttingDown && clientObjs > 0 && pinLibrary()) {
            for (auto& m : s.live.managers) {
                m->live = false;
                retired().managers.push_back(std::move(m));
            }
            for (auto& o : s.live.objects) {
                o->live = false;
                retired().objects.push_back(std::move(o));
            }
            s.live.managers.clear();
            s.live.objects.clear();
            if (s.global)
                wl_global_remove(s.global); // clients are told it is gone; libwayland frees it with the display
            s.global = nullptr;
            gf::log(Log::WARN, "toplevel drag: unloaded with {} client object(s) alive: they stay inert and this library stays in memory", clientObjs);
            return;
        }

        if (!shuttingDown && clientObjs > 0)
            gf::log(Log::ERR, "toplevel drag: could not pin the library: {} client object(s) destroyed; their clients get a protocol error at their next request on them",
                    clientObjs);
        s.live.objects.clear(); // destructors destroy the wl_resources
        s.live.managers.clear();
        if (s.global) {
            wl_global_destroy(s.global);
            s.global = nullptr;
        }
        gf::log(Log::INFO, "toplevel drag: global and {} client object(s) destroyed{}", clientObjs, shuttingDown ? " (shutdown)" : "");
    }

    bool ready() {
        return st().ready;
    }

} // namespace gf::toplevelDrag

#else // GF_TOPLEVEL_DRAG_PROTOCOL

namespace gf::toplevelDrag {

    bool start() {
        gf::log(Log::WARN, "toplevel drag: built without wayland-protocols' xdg-toplevel-drag-v1.xml: no xdg_toplevel_drag_manager_v1");
        return false;
    }

    void stop() {}

    bool ready() {
        return false;
    }

} // namespace gf::toplevelDrag

#endif // GF_TOPLEVEL_DRAG_PROTOCOL
